// Geometry/availability merge + filter semantics.
//
// These are the rules the map's colours depend on, so they are pinned here:
// a plot the API says nothing about is available, a row for a plot that does not
// exist is ignored, and nothing about a villa is ever invented.
//
// Fixtures are explicit rather than generated by a synthetic rule: a rule-based
// fixture would make this file pass regardless of what the real API returns,
// which is the failure mode it exists to catch.

import type { PlotStatusRow, PlotUnitClaim } from '@shadhil/api-types';
import { describe, expect, it } from 'vitest';

import { buildPlots, countByStatus, plotMatchesFilters } from './plot-data';
import { PLOT_GEOMETRY } from './plot-geometry';

/** A row as the API sends it: the plot, its status, and the villas on it. */
function row(
  plotNumber: number,
  status: PlotStatusRow['status'],
  units: PlotUnitClaim[] = [],
): PlotStatusRow {
  return { plotNumber, status, units };
}

/** A villa claiming a plot number, as the API sends it (door number separate). */
function claim(unitNumber: string, plotNumber: number, status = 'SOLD'): PlotUnitClaim {
  return {
    unit: {
      id: `unit-${unitNumber}`,
      phaseId: 'phase-1',
      phaseName: 'Phase A',
      projectId: 'proj-1',
      projectName: 'Demo Villas',
      unitNumber,
      plotNumber,
      bhk: 3,
      facing: 'East',
      sqft: 1450,
      buildupSqft: '1450',
      pricePerSqft: '4000',
      price: '5800000',
      status: status as PlotUnitClaim['unit']['status'],
      createdAt: '2026-10-01T09:00:00.000Z',
    },
    booking: null,
  };
}

describe('buildPlots', () => {
  it('carries the status through and marks everything else available', () => {
    const rows: PlotStatusRow[] = [row(5, 'booked'), row(17, 'blocked')];
    const plots = buildPlots(PLOT_GEOMETRY, rows);
    expect(plots).toHaveLength(125);
    expect(plots.find((plot) => plot.plotNumber === 5)?.status).toBe('booked');
    expect(plots.find((plot) => plot.plotNumber === 17)?.status).toBe('blocked');
    expect(plots.find((plot) => plot.plotNumber === 1)?.status).toBe('available');
  });

  it('reads an empty result as "nothing is sold", not as a failure', () => {
    // The state of a project whose villas have no plot numbers yet, so the
    // endpoint returns no rows. Every plot must still render.
    const plots = buildPlots(PLOT_GEOMETRY, []);
    expect(plots).toHaveLength(125);
    expect(plots.every((plot) => plot.status === 'available')).toBe(true);
  });

  it('ignores a row for a plot that does not exist', () => {
    const plots = buildPlots(PLOT_GEOMETRY, [row(999, 'booked')]);
    expect(plots).toHaveLength(125);
    expect(plots.some((plot) => plot.plotNumber === 999)).toBe(false);
  });

  it('carries the villa behind the plot, with its door number intact', () => {
    // The join is the PLOT number; the door number rides along untouched. A
    // villa whose door number happens to read "20" must not become plot 20.
    const plots = buildPlots(PLOT_GEOMETRY, [row(5, 'booked', [claim('20', 5)])]);
    const plot5 = plots.find((plot) => plot.plotNumber === 5);

    expect(plot5?.units).toHaveLength(1);
    expect(plot5?.units[0]?.unit.plotNumber).toBe(5);
    expect(plot5?.units[0]?.unit.unitNumber).toBe('20');
    expect(plot5?.units[0]?.unit.price).toBe('5800000');
  });

  it('never invents a villa for a plot nothing claims', () => {
    // No row, or a row with no units, means no villa is on the plot. The panel
    // reads that as "not assigned yet" rather than rendering a made-up record.
    const plots = buildPlots(PLOT_GEOMETRY, [row(5, 'booked')]);
    for (const plot of plots) {
      expect(plot.units).toEqual([]);
    }
    expect(plots.every((plot) => plot.units.length === 0)).toBe(true);
  });

  it('gives every plot a stable id and a copied boundary', () => {
    const plots = buildPlots(PLOT_GEOMETRY, []);
    expect(plots[0]?.id).toBe('plot-1');
    // A copy, so a consumer can never mutate the generated geometry.
    expect(plots[0]?.boundary).not.toBe(PLOT_GEOMETRY[0]?.boundary);
    expect(plots[0]?.boundary).toEqual(PLOT_GEOMETRY[0]?.boundary);
  });

  it('carries the measured area across as square feet', () => {
    const plots = buildPlots(PLOT_GEOMETRY, []);
    const geometry = PLOT_GEOMETRY[0];
    expect(geometry).toBeDefined();
    expect(plots[0]?.areaSqFt).toBeCloseTo((geometry?.areaSqM ?? 0) * 10.7639104, 0);
  });
});

describe('countByStatus', () => {
  it('totals to the number of plots and follows the rows it was given', () => {
    const counts = countByStatus(buildPlots(PLOT_GEOMETRY, [row(5, 'booked')]));
    expect(counts.available + counts.booked + counts.blocked).toBe(125);
    expect(counts.booked).toBe(1);
    expect(counts.available).toBe(124);
    expect(counts.blocked).toBe(0);
  });
});

describe('plotMatchesFilters', () => {
  const plots = buildPlots(PLOT_GEOMETRY, [row(20, 'booked')]);
  const plot20 = plots.find((plot) => plot.plotNumber === 20);
  const ewsPlot = plots.find((plot) => plot.plotNumber === 114);

  it('accepts everything by default', () => {
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'all', query: '' })).toBe(true);
  });

  it('treats a partial number as a prefix, so typing narrows live', () => {
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'all', query: '2' })).toBe(true);
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'all', query: '20' })).toBe(true);
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'all', query: '21' })).toBe(
      false
    );
  });

  it('narrows by category and status', () => {
    expect(plotMatchesFilters(ewsPlot!, { category: 'ews', status: 'all', query: '' })).toBe(true);
    expect(plotMatchesFilters(ewsPlot!, { category: 'regular', status: 'all', query: '' })).toBe(
      false
    );
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'booked', query: '' })).toBe(
      true
    );
    expect(plotMatchesFilters(plot20!, { category: 'all', status: 'available', query: '' })).toBe(
      false
    );
  });
});
